// Typed view of bench/cases.json plus argument generation for `argsGen`
// cases (ser-*), shared by the Node runner scripts.
import { Prng } from "./prng.ts";

export type Compare = "exact" | "shape" | "approx" | "ignore";
export interface Case {
  id: string;
  category: string;
  title: string;
  compare: Compare;
  node: { path: string; lib: string | null };
  rust: { path: string; lib: string | null };
  args: Record<string, unknown>;
  argsGen?: { kind: string; [k: string]: unknown };
  phase0: boolean;
  tolerance?: number;
}

/** Args for a case. `argsGen` cases are generated by the ser-* worker (W1-01). */
export function argsFor(c: Case): Record<string, any> {
  if (!c.argsGen) return c.args;
  return generateArgs(c);
}

const UNICODE_POOL = [
  "\u{1F600}", "\u{1F469}‍\u{1F469}‍\u{1F467}‍\u{1F466}", "\u{1F1F5}\u{1F1F9}",
  "日本語", "中文", "한국어", "שלום", "مرحبا بالعالم", "é", "Å", "Å",
  "Ω", "ß", "\u{10348}", "‏", "‮", "\t", "\"", "\\", " ", "abc",
];

/** Deterministic args for `argsGen` cases (mirrored by tests/common/argsgen.rs). */
export function generateArgs(c: Case): Record<string, any> {
  const g = c.argsGen!;
  const seed = c.args.seed as number;
  const p = new Prng(seed);
  let payload: unknown;
  switch (g.kind) {
    case "object": {
      // Convex args allow at most 1024 fields per object: beyond 1000 keys, grow the values instead.
      const total = Math.ceil((g.bytes as number) / 76);
      const n = Math.min(total, 1000);
      const vlen = total <= 1000 ? 64 : Math.ceil((g.bytes as number) / 1000) - 12;
      const o: Record<string, string> = {};
      for (let i = 0; i < n; i++) o[`k${i}`] = p.text(vlen);
      payload = o;
      break;
    }
    case "nested": {
      const depth = g.depth as number;
      const levels: { d: number; s: string }[] = [];
      for (let d = 1; d <= depth; d++) levels.push({ d, s: p.word(8) });
      let cur: any = { leaf: p.text(16) };
      for (let i = depth - 1; i >= 0; i--) cur = { ...levels[i], child: cur };
      payload = cur;
      break;
    }
    case "array_of_objects": {
      const a = [];
      for (let i = 0; i < (g.count as number); i++) {
        a.push({ id: i, name: p.word(8), score: p.below(1000000), x: p.f64() });
      }
      payload = a;
      break;
    }
    case "bytes":
      payload = p.bytes(g.bytes as number).buffer;
      break;
    case "int64": {
      const a: bigint[] = [0n, 1n, -1n, 9223372036854775807n, -9223372036854775808n];
      for (let i = 0; i < 16; i++) {
        const hi = BigInt(p.nextU32());
        const lo = BigInt(p.nextU32());
        a.push(BigInt.asIntN(64, (hi << 32n) | lo));
      }
      payload = a;
      break;
    }
    case "float_specials": {
      const a = [NaN, Infinity, -Infinity, -0, 0];
      for (let i = 0; i < 16; i++) a.push(p.f64() * 1e6 - 5e5);
      payload = a;
      break;
    }
    case "unicode": {
      const a: string[] = [];
      for (let i = 0; i < 64; i++) {
        let s = "";
        for (let k = 0; k < 8; k++) s += UNICODE_POOL[p.below(UNICODE_POOL.length)];
        a.push(s);
      }
      payload = a;
      break;
    }
    default:
      throw new Error(`unknown argsGen kind ${g.kind}`);
  }
  return { seed, payload };
}
